import api from './api';

const orderService = {
  // 获取所有订单 (管理员)
  getOrders: async () => {
    const response = await api.get('/orders');
    return response.data;
  },

  // 获取订单详情
  getOrderById: async (id) => {
    const response = await api.get(`/orders/${id}`);
    return response.data;
  },

  // 创建购买订单
  createPurchaseOrder: async (phoneId) => {
    const response = await api.post('/orders/purchase', { phoneId });
    return response.data;
  },

  // 创建回收订单
  createRecycleOrder: async (recycleData) => {
    const response = await api.post('/orders/recycle', recycleData);
    return response.data;
  },

  // 更新订单状态 (管理员)
  updateOrderStatus: async (id, status) => {
    const response = await api.put(`/orders/${id}/status`, { status });
    return response.data;
  },
};

export default orderService;
